import{c as t,Q as a,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"Squeeze","description":"","frontmatter":{},"headers":[{"level":1,"title":"Squeeze","slug":"squeeze"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"定义原型","slug":"定义原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Reg矢量计算/比较与选择/Squeeze.md","filePath":"api/SIMD-API/基础API/Reg矢量计算/比较与选择/Squeeze.md"}'),d={name:"api/SIMD-API/基础API/Reg矢量计算/比较与选择/Squeeze.md"};function l(r,e,i,p,o,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="squeeze" tabindex="-1">Squeeze <a class="header-anchor" href="#squeeze" aria-label="Permalink to &quot;Squeeze&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将传入的srcReg中被mask选择的有效元素依次复制到dstReg中，有效元素在dstReg中从低到高连续排列。dstReg中剩余位置元素置为0。</p><h2 id="定义原型" tabindex="-1">定义原型 <a class="header-anchor" href="#定义原型" aria-label="Permalink to &quot;定义原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T = DefaultType, GatherMaskMode store = GatherMaskMode::NO_STORE_REG, typename U&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void Squeeze(U&amp; dstReg, U&amp; srcReg, MaskReg&amp; mask)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>T表示目的操作数和源操作数的数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t/int8_t/uint16_t/int16_t/uint32_t/int32_t/half/float</td></tr><tr><td>store</td><td>GatherMaskMode选择是否将有效元素的总字节数存入AR寄存器，AR寄存器描述参考表1。 NO_STORE_REG，有效元素的总字节数不存入AR寄存器；STORE_REG，有效元素的总字节数存入AR寄存器。</td></tr><tr><td>U</td><td>srcReg/dstReg RegTensor类型， 例如RegTensor&lt;uint32_t&gt;，由编译器自动推导，用户不需要填写。</td></tr></tbody></table><p><strong>表 2</strong> 函数参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstReg</td><td>输出</td><td>目的操作数。 类型为RegTensor。</td></tr><tr><td>srcReg</td><td>输入</td><td>源操作数。 类型为RegTensor</td></tr><tr><td>mask</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>当store取值为STORE_REG时，由于硬件约束，StoreUnAlign指令和Squeeze指令必须交替使用，例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Squeeze(dstVreg, srcVreg, mask);</span></span>
<span class="line"><span>StoreUnAlign(dstAddr, dstVreg, ureg);</span></span>
<span class="line"><span>Squeeze(dstVreg, srcVreg, mask);</span></span>
<span class="line"><span>StoreUnAlign(dstAddr, dstVreg, ureg);</span></span></code></pre></div><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template&lt;typename T&gt;</span></span>
<span class="line"><span>__simd_vf__ inline void SqueezeVF(__ubuf__ T* dstAddr, __ubuf__ T* srcAddr, uint32_t oneRepeatSize, uint16_t repeatTimes)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg0;</span></span>
<span class="line"><span>    AscendC::Reg::RegTensor&lt;T&gt; srcReg1;</span></span>
<span class="line"><span>    AscendC::Reg::UnalignRegForStore ureg;</span></span>
<span class="line"><span>    AscendC::Reg::MaskReg sqzMask = AscendC::Reg::CreateMask&lt;T, AscendC::Reg::MaskPattern::H&gt;();</span></span>
<span class="line"><span>    for (uint16_t i = 0; i &lt; repeatTimes; ++i) {</span></span>
<span class="line"><span>        AscendC::Reg::LoadAlign&lt;T, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(srcReg0, srcAddr, oneRepeatSize);</span></span>
<span class="line"><span>        AscendC::Reg::Squeeze&lt;T, AscendC::Reg::GatherMaskMode::STORE_REG&gt;(srcReg1, srcReg0, sqzMask);</span></span>
<span class="line"><span>        AscendC::Reg::StoreUnAlign&lt;T, AscendC::Reg::PostLiteral::POST_MODE_UPDATE&gt;(dstAddr, srcReg1, ureg);</span></span>
<span class="line"><span>     }</span></span>
<span class="line"><span>     AscendC::Reg::StoreUnAlignPost(dstAddr, ureg);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,17)])])}const u=t(d,[["render",l]]);export{h as __pageData,u as default};
